INSERT INTO dbo.OperatorMasters
      (ServiceID, OperatorName, MinimumRechargeAmount, MaximumRechargeAmount, RepeatRechargeInMinute,
       BlockedTill, OperatorImagePath, Opcode, BusinessModel, NumberLength, HSNCode, Prefix,
       AccountStartWith, SequenceLogic, MinLength, MaxLength, AccountName, Remark, TollFreeNumber,
       UISequence, BlockedAmount, AllowedFor, IsActive, IsDelete, IsTimelyBlocked, IsRandom, IsBBPS,
       IsBillFetch, IsPartialBill, IsViewRequired, IsDenominationApplicable,
       [DateTime], UpdatedateTime, IsDeleted)
SELECT s.ServiceID, src.OperatorName, src.MinimumRechargeAmount, src.MaximumRechargeAmount, 0,
       CAST('1900-01-01' AS datetime2(7)),
       N'', src.Opcode, N'', src.MaxLength, N'', N'',
       N'', N'', src.MinLength, src.MaxLength, src.AccountName, src.Remark, N'',
       src.UISequence, 0, N'',
       -- INACTIVE on purpose: a biller nobody can serve must not reach the list.
       0, 0, 0, 0, 1,
       src.IsBillFetch, src.IsPartialBill, 0, 0,
       @now, @now, 0
FROM   src
JOIN   dbo.ServiceMasters s
       ON s.Name = src.ServiceName AND s.ServiceCategory = src.ServiceCategory AND s.IsDeleted = 0
WHERE  NOT EXISTS (
    SELECT 1 FROM dbo.OperatorMasters o
    WHERE  o.ServiceID = s.ServiceID AND o.OperatorName = src.OperatorName AND o.IsDeleted = 0)
AND    NOT EXISTS (
    SELECT 1 FROM dbo.OperatorMasters o WHERE o.Opcode = src.Opcode AND o.IsDeleted = 0);

PRINT CONCAT('Billers added: ', @@ROWCOUNT);

/* ------------------------------------------------- the inputs each biller asks for
   One row per field the biller needs before a bill can be fetched, in its own order;
   the amount is not here, it is the amount box on the payment screen.

   Only billers that have NO field configuration yet are filled in, so a client who has
   already tuned a biller's screen by hand keeps exactly what they set.                */
