INSERT INTO dbo.BBPSConfigurations
      (OperatorID, Label, [Type], PlaceHolder, IsRequired, ErrorMeeage, Sequence, [Length],
       ConfigList, IsDisplay, [DateTime], UpdatedateTime, IsDeleted)
SELECT o.OperatorID, src.Label, src.[Type], src.PlaceHolder, 1,
       CONCAT(N'Please enter a valid ', src.Label, N'.'),
       src.Sequence, src.[Length], src.ConfigList, 1, @now, @now, 0
FROM   src
JOIN   dbo.OperatorMasters o ON o.Opcode = src.Opcode AND o.IsDeleted = 0
WHERE  NOT EXISTS (
    SELECT 1 FROM dbo.BBPSConfigurations b
    WHERE  b.OperatorID = o.OperatorID AND b.IsDeleted = 0);

PRINT CONCAT('Biller input fields added: ', @@ROWCOUNT);
